typedef unsigned char u_char;
typedef unsigned int u_int;

struct nglTexture
{
  char Padding[12];
  u_int Hash;
};

struct nglQuadVertex
{
  float X, Y;
  float U, V;
  u_int Color;
};

struct nglQuad
{
  nglQuadVertex Verts[4];
  float Z;
  u_int MapFlags;
  u_int BlendMode;
  u_int BlendModeConstant;
  nglTexture* Tex;
};

typedef void (*nglCustomNodeFn)( u_int*& Packet, void* Data );

struct nglSortInfo
{
  u_int Type;
  union {
    float Dist;
    u_int Hash;
  };
};

enum
{
  NGLSORT_TRANSLUCENT,
  NGLSORT_TEXTURED,
  NGLNODE_QUAD = 2,
};

extern "C" void* memcpy( void* Dest, const void* Src, unsigned int Size );
void* nglListAlloc( u_int Bytes, u_int Alignment = 4 );
void nglListAddNode( u_int Type, nglCustomNodeFn NodeFn, void* Data, nglSortInfo* SortInfo, u_char **Buf = 0 );
void nglVif1RenderSingleQuad( u_int*& Packet, void* Param );

inline void nglGetSortInfo( nglSortInfo* SortInfo, u_int BlendMode, nglTexture* Tex, float Dist )
{
  if ( BlendMode == 0 || BlendMode == 1 )
  {
    SortInfo->Type = NGLSORT_TEXTURED;
    if ( Tex )
      SortInfo->Hash = Tex->Hash;
    else
      SortInfo->Hash = 0;
  }
  else
  {
    SortInfo->Type = NGLSORT_TRANSLUCENT;
    SortInfo->Dist = Dist;
  }
}

#define nglListNew( Type ) (Type*)nglListAlloc( sizeof(Type) )

void nglListAddQuad( nglQuad* Quad )
{
  nglQuad* Entry = nglListNew( nglQuad );
  if ( !Entry )
    return;
  memcpy( Entry, Quad, sizeof(nglQuad) );

  nglSortInfo SortInfo;
  nglGetSortInfo( &SortInfo, Entry->BlendMode, Entry->Tex, Entry->Z );
  nglListAddNode( NGLNODE_QUAD, nglVif1RenderSingleQuad, Entry, &SortInfo );
}
